fields.InputDefinition:
{
  "goal": "Using the application switcher dropdown next to the logo (NOT the Ctrl+K search box), open the Communication app, then open its Templates section. Confirm the templates list renders (it has many template rows), then open one template and confirm its editor/detail view appears showing the template's CONTENT — a 'Contents' section with the template Text (which may include mustache-style placeholder parameters written in double curly braces) and possibly a 'Template Includes' area. (These are MJ Templates whose body is the Contents/Text — there is NOT a separate 'subject'+'body' field pair, so do not look for those.) Pages can take 10-30s to load in this resource-constrained environment - wait, do not navigate away.",
  "startUrl": "http://localhost:4200/app/communication",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}
